REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (48, 'zhCN', '嗝！呵呵！你还想再来一段？在南边藤蔓盘绕蔓延的土地上，藏着一口隐秘的水井，井水幽深，纯净得如同圣光的圣女。现在就给我带些圣泉之水来吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (432, 'zhCN', '这简直气死我了！嗷呜……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (476, 'zhCN', '以星辰之名！这实在令人不安！$B $B 过去我们曾饱受熊怪腐化之苦，但自从泰达希尔得到净化之后，这样的麻烦早该过去了。如果连守护巨龙们的祝福都无法救赎我们的大树，我不禁要为我们全体同胞感到忧心。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1361, 'zhCN', '我发现你的活儿没干完啊，$N。难道要我告诉夏琳德拉你很蠢吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1390, 'zhCN', 'NULL', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (1822, 'zhCN', '我会留下你归还给我的三件武器，作为我痛苦与失去的纪念。但是，$n，请从这些传家宝中挑出你最喜欢的一件，留给自己吧。$B$B愿它为你效力，胜过它曾效力的那些被诅咒的前任主人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (3570, 'zhCN', '你知道这一切的结局，不是吗，$n？她绝对活不成了……看看她。现在对她来说最好的事，就是帮助我们寻找瘟疫的解药。她喝下的这潭水也许藏有线索，能帮我们弄清该怎么做。反正她都要死了——不如在死前为我们的人民做一件高尚的事。你说是不是？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (6344, 'zhCN', '有什么可以帮你的？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7321, 'zhCN', '原料找齐了吗？实话跟你说，联盟的蛆虫现在已经在这片区域泛滥成灾了……依我看，他们已经逼近得太过了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (7704, 'zhCN', '好大一个枕头啊！你从哪儿弄来的？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8101, 'zhCN', 'NULL', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8103, 'zhCN', '哈卡莱人害怕你了，$n。他们口中讲述着种种恐怖的事迹，还以为唯有他们那无面的神才做得出来。你用卡贾罗之力灼烧了他们。如今他们从两个地方尝到了恐惧的滋味。$b$b是时候进一步强化这块卵石了。把护符交给我吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8110, 'zhCN', 'NULL', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8116, 'zhCN', 'NULL', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8322, 'zhCN', '酒桶里已经装满了麦酒。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8328, 'zhCN', '啊，$n——我记得你是这座岛上新来的法师之一，对吧？那你可来对地方了。如果你追求的是奥术造诣，我就能传授这样的知识——前提是你付得起训练费用，而且能专心听我讲课。
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8563, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8564, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8661, 'zhCN', '在他位于安其拉的居所里，恐怖的克苏恩正在沉睡中等待。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8741, 'zhCN', '<阿纳克洛斯点了点头。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8742, 'zhCN', '一千年过去了，正如命运所注定，有一个人站在了我的面前。一个将引领他的人民走向新时代的人。$B$B上古之神在颤抖，$n。哦没错，它畏惧你的信念。粉碎克苏恩的预言吧。$B$B它知道你来了，勇者——与你同来的还有整个卡利姆多的力量。你只需在准备就绪时告知我，我便将流沙节杖授予你。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8763, 'zhCN', '这台“冬青保鲜机”乍一看像某种蒸馏器，但仔细检查后你会发现它被做了些地精风格的改动。不过，凭借你的烹饪技能，你似乎能弄明白这台机器的运作原理。机器里已经放好了新鲜的冬青——你只需提供一些深岩盐和五枚金币，就能让机器运转起来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8799, 'zhCN', '这台“冬青保鲜机”乍一看像某种蒸馏器，但仔细检查后你会发现它被做了些地精风格的改动。不过，凭借你的烹饪技能，你似乎能弄明白这台机器的运作原理。机器里已经放好了新鲜的冬青——你只需提供一些深岩盐和五枚金币，就能让机器运转起来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (8846, 'zhCN', '啊，你是来为自己换取更多补给的吧？我完全理解对额外军需的渴求……只要环顾四周，你就明白了。$B$B我会发放一些额外补给给你，但你必须交给我相应数量的嘉奖徽记作为交换。以这种方式上缴徽记不会为你赢得任何嘉奖，但当战火最终燃起之时，你也许能找到些有助于保命的好东西。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9120, 'zhCN', '圣光在上！你身上带着什么污秽之物，$g？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9154, 'zhCN', '你是来加入我们教团的，对吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9177, 'zhCN', '那么，你是谁？你手里拿的是什么？那条项链看起来有点眼熟。把它给我！', 0);
