REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9264, 'zhCN', '唔。根据你的叙述，那些圆圈中的声音……一定是用于某种交流的。一想到通过这种魔法联系上的是怎样扭曲的心智，我就不寒而栗。不过，你似乎毫发无损、神志清醒地回来了。银色黎明感谢你的效劳。', 0);
