REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9949, 'zhCN', '桑德跟我说过他的计划。你拿到眼睛了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9974, 'zhCN', '你把剩下的材料都带来了吗？', 0);
