REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (9985, 'zhCN', '那段文字看起来很眼熟。没错，确实是鸦人文字，但我认不出这个印记。', 0);
