REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10195, 'zhCN', '自从你送来第一批羽毛、我做完了贝特尔姆的那顶帽子之后，其余的雇佣兵都吵着也要一顶，连桑德尔也不例外。我答应他们马上就做，不过这项活儿需要源源不断的鸦人羽毛。
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10196, 'zhCN', '我在把鸦人灵魂引到自己身边这件事上已经取得了一些进展，但它们依然十分羞怯。或许只要我改进一下伪装，它们在入定状态中就会更愿意靠近我。
