REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11052, 'zhCN', '<阿达尔注意到你走了过来，一道温暖的光芒将你笼罩。阿达尔似乎知道你有东西要交给他。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11196, 'zhCN', '这个新督军必须倒台，否则赞达拉人就要在这里永久扎根了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11403, 'zhCN', '$n，很高兴再次见到你。我相信孩子们一定爱听你的英雄事迹。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11494, 'zhCN', '进展如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11693, 'zhCN', '看起来被放倒的瘟疫猛犸人还不够多，$C。$B$B你能在回来之前再解决掉几只吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11694, 'zhCN', '时间紧迫，$C。我们最不想看到的就是不得不去面对瘟疫猛犸人。$B$B光是普通猛犸人就已经够难对付了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11698, 'zhCN', '你绝不可能在这么短的时间里杀掉这么多天灾军团的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (11821, 'zhCN', '向纳格兰的火焰致敬！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (12446, 'zhCN', '又给我弄到一些115号元素了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (12879, 'zhCN', '有人正在利用意志熔炉制造这支大军……奥杜尔已经不再安全了。$r，你把核心找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13325, 'zhCN', '看来你已经成功凑齐了一副混沌套牌！恭喜你！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13327, 'zhCN', '看来你已经成功凑齐了一副亡者套牌！恭喜你！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13421, 'zhCN', '又发现永冻冰了吗，小$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13475, 'zhCN', '许多英勇的战士都敬仰你，$n。在与联盟的战斗中，你依然是所有人的楷模。你此行有什么消息要带回来吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13477, 'zhCN', '啊，$N。希望你能继续在各条战线上贡献自己的经验。我们许多在前线作战的年轻战士都非常敬仰你这样经验丰富的老兵。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13505, 'zhCN', '你找到什么遗物了吗？', 0);
