REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13526, 'zhCN', '你收集到熊掌了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13527, 'zhCN', '欢迎回来！你找到我要找的熊类样本了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13528, 'zhCN', '<嗡嗡盒723期待地朝你嗡嗡作响。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13537, 'zhCN', '就算用言语也无法表达得更好了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13544, 'zhCN', '你去看过那座古老的熊雕像了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13554, 'zhCN', '你拿到那些东西了吗？我越早开始研制解药，就能拯救越多的动物！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13557, 'zhCN', '什么事，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13558, 'zhCN', '你回来了。有什么消息吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13563, 'zhCN', '不知为何，我躲过了那种让其他幸存者饱受折磨的毒素。不过，我在某种程度上还是忍不住羡慕他们……独自永生，似乎根本算不上真正地活着。$B$B我非常想念你，阿纳雅。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13566, 'zhCN', '你把我需要的材料找回来了吗？还有，请告诉我你在过程中没有伤害任何动物……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13578, 'zhCN', '你带来的是别人的羽毛？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13582, 'zhCN', '你有火把？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13587, 'zhCN', '你找到了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13590, 'zhCN', '你好啊，$c。你把箭带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13591, 'zhCN', '你回来了！听说战斗进行得很顺利。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13596, 'zhCN', '你拿到图纸了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13598, 'zhCN', '凶爪可是个相当凶悍的战士。尽管那些偷猎者居心叵测，我还是有点为他们感到惋惜。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13615, 'zhCN', '我们需要的箭你收集齐了吗，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13619, 'zhCN', '你找到戈拉特了吗，$c？！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13620, 'zhCN', '你手里拿着的是什么，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13622, 'zhCN', '正在等待输入。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13623, 'zhCN', '在这种形势下你还敢来这里，胆子真不小。你有什么事，陌生人？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13626, 'zhCN', '我们在这里的损失极其惨重。', 0);
