REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13631, 'zhCN', '你准备好了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13635, 'zhCN', '是什么风把你吹到这儿来的？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13640, 'zhCN', '你拿到需要的木材了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13642, 'zhCN', '你去法拉希姆湖取艾露恩之光的时候没遇到什么麻烦吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13645, 'zhCN', '我是瑞恩·狼行者。你是谁？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13651, 'zhCN', '我们需要的油你收集到了吗，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13698, 'zhCN', '时间不多了，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13796, 'zhCN', '$n，你回来了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13797, 'zhCN', '我们需要的矿石你收集齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13819, 'zhCN', '你准备好了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13831, 'zhCN', '这是什么？你在洞穴里还找到了别的东西？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13842, 'zhCN', '你把敌人的首级带来了吗，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13844, 'zhCN', '纳拉辛已经不用我们操心了，但如果他毕生的成果落入敌人之手，数百年积累的黑暗智慧就可能被召唤出来，降临到我们头上。追捕进行得怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13868, 'zhCN', '什么事让你烦心，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13869, 'zhCN', '你拿到遗骸了吗，小家伙？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13871, 'zhCN', '我只想知道一件事，$r。那个刺客死了没有？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13872, 'zhCN', '<你走上前时，狼人一脸茫然地看着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13874, 'zhCN', '你认为你已经把刺背要塞里的巨魔护符全都取回来了吗？只要还有一个遗漏，刺背部族就会继续受到它们的影响，最终他们会袭击这个地方。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13875, 'zhCN', '你好，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13876, 'zhCN', '怎么样？刺背部族的未来就压在你的肩上了，$r。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13880, 'zhCN', '完成了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13882, 'zhCN', '生命是强大的，$n。当它以最纯粹的形式凝聚起来时，便能战胜一切。总有一天，就连黑海岸也会从创伤中痊愈。我需要的东西你都找齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13883, 'zhCN', '你把那块装甲板拿回来了吗，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13891, 'zhCN', '我都不敢问，$n。神器被摧毁了吗？它的守护者怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13909, 'zhCN', '这下够湿了吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13910, 'zhCN', '我们新的海景公寓怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13912, 'zhCN', '你找到了吗？格罗夫想尽快离开这片废墟！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13918, 'zhCN', '你把开槽装置的所有零件都组装好了吗？我们可能得把勘探员雷姆特维尔的三明治从古老的数据接口上取下来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13920, 'zhCN', '什么事，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13922, 'zhCN', '要确保治好那个女孩，需要五块月长石。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13924, 'zhCN', '$n，是你吗？你带着瑞拉拉的治疗药物回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13925, 'zhCN', '就在我们说话的当口，你带着的那株树苗也在不断成长壮大。生命具有再生之力，$n。它起作用了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13928, 'zhCN', '你竟然突破了部落的防线进到这里，真让我惊讶，$r。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13942, 'zhCN', '让我看看你给我带来了什么，$r。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13945, 'zhCN', '它们的数量减少了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13946, 'zhCN', '你帮我们击溃那些小格雷尔了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13949, 'zhCN', '莫克拉，陌生人。你是从远望哨来的吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13961, 'zhCN', '对我们抓来的俘虏别太粗暴，等他回答我们的问题时，脑袋还得好好待在脖子上呢。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13967, 'zhCN', '那么，$n。事情办妥了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13970, 'zhCN', '那只生物没有抬起头，只是用一双水汪汪的大眼睛眼巴巴地望着你。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13975, 'zhCN', '我上次那支商队尾部挥舞着枪的家伙，是你吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13977, 'zhCN', '老大，你那儿有什么东西？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13979, 'zhCN', '你让那个满身肉疣的恶心地精永远闭嘴了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13982, 'zhCN', '如果我们要获得自由，就必须得到卡利瓦的心脏。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13983, 'zhCN', '朋友，我需要的那些零件你都弄到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13988, 'zhCN', '汤加对这片土地的了解胜过我们所有人，我相信，眼睁睁看着它被撕裂，对他来说是实实在在的痛楚。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (13999, 'zhCN', '你是谁？是海尔布里姆派你来的吗？行事低调点。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14003, 'zhCN', '你是说……萨姆福朗格！？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14004, 'zhCN', '这是我的萨姆福朗格吗？我差点都认不出来了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14005, 'zhCN', '你找到腐化的源头了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14006, 'zhCN', '你找到科珀普拉格了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14014, 'zhCN', '扔炸弹的猴子？！简直胆大包天！！！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14034, 'zhCN', '你拿到货了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14039, 'zhCN', '近来如何，年轻人？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14049, 'zhCN', '长滩男爵还活着吗？你有什么东西要交给我吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14050, 'zhCN', '我要闭上眼睛了，$n。等我睁开眼的时候，我希望看到满眼的财宝。成交吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14056, 'zhCN', '你把钱带来了？这笔钱能让那些没心没肺、鲁莽无情的杀手们回心转意，作用可大了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14057, 'zhCN', '是枪，老兄。你把东西带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14063, 'zhCN', '我看到远处起锚的那艘船，是少女之匕号吗？这事儿跟你有关吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14067, 'zhCN', '你看起来伤得不轻，$c。是不是跟那些窃贼搏斗过了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14068, 'zhCN', '小迅猛龙龙们在哪儿呀？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14072, 'zhCN', '去搜查那些帐篷，$n。尽量别管那股恶臭。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14093, 'zhCN', '狼人解决掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14094, 'zhCN', '你把物资抢救回来了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14095, 'zhCN', '你找到了什么，勇士？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14096, 'zhCN', '你解救出库尔和那些毫无希望的学员了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14103, 'zhCN', '你好，$n！你有什么要交易的吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14109, 'zhCN', '全都买齐了吗，$n？我都等不及看你穿上了！$B$B你买的是好货，对吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14110, 'zhCN', '全都买齐了吗？我都等不及看你穿上了！嗯哼！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14118, 'zhCN', '你身上有一股新鲜猎物的气味，$c。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14121, 'zhCN', '你把那一大堆偷来的赃物又偷到手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14122, 'zhCN', '你拿到了吗？你撬开保险柜，把你自己的钱财从银行里取出来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14123, 'zhCN', '老大，货拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14124, 'zhCN', '你有多少卡亚矿？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14126, 'zhCN', '哦，$n，是你啊。真是个意想不到的惊喜。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14127, 'zhCN', '你说你在其中一具尸体上找到了东西？快拿来给我看看！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14128, 'zhCN', '相信你这次来打扰是有要紧事吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14129, 'zhCN', '<劳工队长格拉比特的声音夹杂着杂音从无线电中传来。>$B$B嘿，$n！你能收到吗？$B$B驾驶那家伙可简单了。要控制踏板就踩踏板，呃，要控制拉杆就扳拉杆。明白了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14131, 'zhCN', '太累了，很难集中精神。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14134, 'zhCN', '木头加工进行得怎么样了？你真该看看那玩意儿把西兰花绞成什么样！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14138, 'zhCN', '呃……一切都进展顺利。是啊。那是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14142, 'zhCN', '你把库尔和那些毫无希望的见习者都救出来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14151, 'zhCN', '你完成转化了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14154, 'zhCN', '快好了！小心点，不然我们会失去他的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14190, 'zhCN', '<奇怪的地精扩音器发出嘶嘶的噼啪杂音。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14192, 'zhCN', '<武器柜里塞满了穷凶极恶而又残破不堪的实验装置，有些上面甚至还连着地精的肢体。你发现那台激光钻头正被悉心安放在一个衬有天鹅绒的木箱里。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14194, 'zhCN', '嘿，瞧啊，你的四肢都完好无损。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14197, 'zhCN', '你把我的货物都准备好了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14201, 'zhCN', '你为我干过脏活了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14202, 'zhCN', '一群死掉的精灵可挡不住进步的脚步。只要有我在，就休想！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14204, 'zhCN', '弄好了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14209, 'zhCN', '玛吉妮真是一台了不起的机器，不是吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14216, 'zhCN', '你在湖边有什么发现吗？你浑身都湿透了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14217, 'zhCN', '火盆静静地等待着祭品。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14219, 'zhCN', '雕像满怀期待地伫立着。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14222, 'zhCN', '我们能行的，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14225, 'zhCN', '绝不能让燃烧之刃的阴谋得逞！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14230, 'zhCN', '瞧瞧，你又回来了……又来跟我说话了。我想，这意味着你已经拿到了我的书吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14232, 'zhCN', '你手里拿的是什么，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14233, 'zhCN', '$n，你在洞穴里发现什么有趣的东西了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14234, 'zhCN', '你一定是乘坐那艘沉没的$r奴隶船来的。你手里拿的是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14241, 'zhCN', '嗯，这看起来像是过度复杂的侏儒工程学产物，带着一大堆不必要的仪表和安全措施。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14249, 'zhCN', '我的袍子看起来相当不错。你把那些羽毛带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14250, 'zhCN', '我听到了几声爆炸。我实在分不清其中哪一声是不是你弄出来的……这些地精有时候真是烦人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14251, 'zhCN', '朋友，让我瞧瞧那些蝎尾吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14252, 'zhCN', '找尾巴的进展如何，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14253, 'zhCN', '找扑击鸟的进展如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14254, 'zhCN', '你手里拿的是什么，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14257, 'zhCN', '你把我需要的那些部件收集齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14258, 'zhCN', '希望你能再给我带点弹药来。我在这边除了耍嘴皮子，就没别的可打了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14263, 'zhCN', '你把我要的百里香带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14268, 'zhCN', '难道是……？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14270, 'zhCN', '纳迦的能量石发出期待的嗡嗡声，不住地脉动着。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14274, 'zhCN', '你干得不错，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14276, 'zhCN', '你学得真快。我们要让这群狼人瞧瞧，谁才是真正的猎人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14279, 'zhCN', '亲爱的，你学得真快。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14281, 'zhCN', '我一直都知道你是个一点就通的家伙！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14282, 'zhCN', '$c，你都学到了些什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14283, 'zhCN', '大地在向我们诉说，$n。即便身处这般险境，它也不会弃我们而去。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14304, 'zhCN', '你把我需要的样本找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14305, 'zhCN', '你把我需要的样本收集齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14308, 'zhCN', '<格里利尖细刺耳的声音从一组扬声器中传出。>$B$B火箭道呼叫秘密实验室！火箭道呼叫秘密实验室！秘密实验室，收到请回答……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14310, 'zhCN', '别担心实验室里那些燃烧的化学药剂留下的后遗症。头发还会再长出来的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14316, 'zhCN', '$n，你找到我们的东西了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14323, 'zhCN', '艾萨拉海海绵内含活水，微微起伏涌动着。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14324, 'zhCN', '你回来了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14325, 'zhCN', '你给我族带来食物了吗，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14339, 'zhCN', '这么快就回来了，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14351, 'zhCN', '你怎么还在这儿，不去战场上拼杀，$C？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14352, 'zhCN', '$n，你想干什么？最好是有要紧事。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14353, 'zhCN', '据说这个马尔辛就在剃刀高地外面。毫无疑问——他必须死。$b$b我在奥格瑞玛的线人告诉我，他们的侦察兵在那边发现了瘟疫的迹象。野猪人也显出了感染瘟疫的征兆；他们变得强大得多。无论天灾在那里搞什么鬼名堂，都必须终结。立刻。$b$b找到这个马尔辛，杀了他。等他死了再回来向我汇报。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14362, 'zhCN', '$c，你手里拿的是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14363, 'zhCN', '决不能让燃烧之刃的阴谋得逞！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14368, 'zhCN', '我……我不知道没有他们，我还能不能撑下去。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14369, 'zhCN', '$n，你把那个被遗忘者的渣滓解决掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14370, 'zhCN', '你还有更多样本吗？粗心大意的冒险者们抢夺这种东西已经好多年了——他们根本不知道它有多珍贵！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14371, 'zhCN', '我或许应该提醒你一句，雾翼奇美拉是会放射闪电的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14378, 'zhCN', '怎么样，$c？找到那个蠢货了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14379, 'zhCN', '你收集到一些龙虾怪的尾巴了吗，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14382, 'zhCN', '你回来了，$n。外面情况如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14385, 'zhCN', '拿到泻药之后，想办法喂给戈尔蒙甘吃。也可以顺手给他一本杂志什么的。为了科学，放手去干吧！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14386, 'zhCN', '事情办妥了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14390, 'zhCN', '<艾索雷苟斯怒视着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14395, 'zhCN', '我们剩下来的人已经不多了，$n。我们必须照顾好那些幸存的吉尔尼斯人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14399, 'zhCN', '近来可好，亲爱的？要不要留下来喝杯茶？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14400, 'zhCN', '东西都顺利找到了吗，亲爱的？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14401, 'zhCN', '你真是个招人喜欢的小伙子，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14404, 'zhCN', '我的补给品带来了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14408, 'zhCN', '我怀疑档案就在附近，$n。找到那些图纸！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14412, 'zhCN', '该死的被遗忘者！连海洋都不愿意接纳他们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14418, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14419, 'zhCN', '你好。有什么我能为你效劳的吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14420, 'zhCN', '有捷报要汇报吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14421, 'zhCN', '成功了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14423, 'zhCN', '玛吉妮近来如何？她又像从前那样欢快地跑起来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14428, 'zhCN', '$n，你联系上他们了吗？有什么能告诉我的？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14429, 'zhCN', '$n，是你吗？这块石头的显示效果真是糟透了。他们用的都是些什么破设备？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14431, 'zhCN', '黑颚部族十分凶悍。他们一旦组织起来，就会对我们在这里的工作造成极大的破坏。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14432, 'zhCN', '狩猎进行得如何？我自己尝过一次那荆根，苦得很，就连我这个吃碎石的老家伙都受不了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14433, 'zhCN', '你拿到长袍了吗？安多瑞尔正在为我们准备一些可用的魔法。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14435, 'zhCN', '如果我们的诡计得逞，$n，我们就能永远在联盟和黑颚部族之间制造裂痕。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14438, 'zhCN', '如果苍白鬃部族当初能更尊重这片土地和这里的居民，这场冲突根本就不会发生。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14443, 'zhCN', '你手里拿的是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14456, 'zhCN', '见习者，你给我带来了多少？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14457, 'zhCN', '你在那个密探身上找到什么有用的东西了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14460, 'zhCN', '你完成试炼了吗，年轻人？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14464, 'zhCN', '想必你带来了好消息，$n？', 0);
