REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14483, 'zhCN', '你把那些净耍阴谋诡计的恶徒解决掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14486, 'zhCN', '血精灵们特别追捧那些石板，肯出大价钱呢。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14487, 'zhCN', '我最喜欢人家把无价的神器就那么随手丢在一旁了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (14491, 'zhCN', '土地满意了吗？', 0);
