REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24439, 'zhCN', '贾罗德努斯还在吠着发号施令吗，还是你已经替他卸下了脑袋的重担？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24440, 'zhCN', '别耽搁了，$N。冬蹄水井必须得到净化！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24441, 'zhCN', '$n，我派你去收集的爪子拿到了吗？雷角水井每过一个小时就变得更加污浊！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24449, 'zhCN', '啊，这不是当今的风云人物嘛！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24451, 'zhCN', '你从龙眠神殿把那本书取回来了吗？', 0);
