REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24685, 'zhCN', '把图纸给我，快点！我们的时间不多了。
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24686, 'zhCN', '你拿到种子了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24691, 'zhCN', '我要好多好多，因为我得付运费、搬运费、宣传费……哦对了，还有要付给你的报酬。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24699, 'zhCN', '全指望你了，$n。我在这个“焦油当胶水”的计划里可是砸了大本钱的，你要是两手空空地回来，那可就太说不过去了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24700, 'zhCN', '你拿到焦油花了吗？我怎么没看见……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24701, 'zhCN', '你找到什么好东西了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24702, 'zhCN', '健壮的坐骑，忠实的朋友。大灾变之后不久便离世而去。它生前最讨厌嘈杂的声响。请勿献花，送上几株血瓣花苗即可。那是它一生最爱之物。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24708, 'zhCN', '你有什么发现吗？成功了没有？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24709, 'zhCN', '事情办妥了吗？你设法把他的笔记抢救出来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24715, 'zhCN', '<阿米01进入了省电模式。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24717, 'zhCN', '我从来都不知道现在流行什么款式，所以我想要几种不同的颜色。尽量把那里每种不同猩猩的毛皮都弄一些来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24718, 'zhCN', '红色毛皮？你还等什么！赶紧回去把那只红色猩猩抓来！我付你双倍的价钱！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24719, 'zhCN', '你拿到爪子了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24720, 'zhCN', '我就知道我快有大发现了，$n！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24730, 'zhCN', '随你怎么看我吧，但那些人根本不会在意他们拿去研究的骨头是来自远古的剑龙和双刃龙，还是我们扎营时差点把我们囫囵吞下的那些家伙。只要能活着离开这里，我就心满意足了……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24731, 'zhCN', '别把我的话当耳旁风，$n。如果你真想面对这个生物，就必须谨慎行事……而且要机智。要引出拉''科尔维并击败它，需要强大的力量和过人的洞察力。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24732, 'zhCN', '小心，$n。靠近任何一窝蛋都肯定会激怒那些母亲……即使你已经从其中一只身上取得了腺体。为了保护幼崽而战的母亲们，凶残程度绝不亚于拉''科尔维。不过，如果你成功了，我们就有万无一失的办法把拉''科尔维从藏身处引出来了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24733, 'zhCN', '不要被恐惧压倒，$n。恐惧是最大的背叛者……你必须保持坚强！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24734, 'zhCN', '林戈的袋子就放在你面前的岩石上。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24736, 'zhCN', '每辆伟大的载具都需要一个名字……我想就叫它……完爆号！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24737, 'zhCN', '塔拉又成功了——这种超强力粘合剂一定会风靡一时！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24740, 'zhCN', '你觉得这座火山是活火山吗？真奇怪，大灾变来袭的时候它怎么没有爆发呢。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24741, 'zhCN', '你弄到多少个了？我已经能尝到我们马上要做的那份超大煎蛋卷的味道了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24742, 'zhCN', '我本来想亲自去一趟，可是……我有点怕那里的火元素！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24744, 'zhCN', '想想看，等我们带回有史以来最大的蛋时，赞美之声将如雨点般落到我的头上……落到我们的头上！', 0);
