REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24902, 'zhCN', '你找到她了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24904, 'zhCN', '不……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24906, 'zhCN', '让我看看你带了什么来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24912, 'zhCN', '<大领主达里安·莫格莱尼郑重其事地向你开口。>$B$B影之锋已经做好了接受最后力量灌注的准备。$B$B铸造影之哀伤的时刻到了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24915, 'zhCN', '你手中拿的是什么，$c？$B$B它在向我呼唤，唤起了我以为早已消逝的情感。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24916, 'zhCN', '是的，$c？我能为你做些什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24917, 'zhCN', '你手里拿的是什么，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24918, 'zhCN', '什么事，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24919, 'zhCN', '我能为你效劳些什么，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24920, 'zhCN', '事情办好了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24926, 'zhCN', '这……这是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24930, 'zhCN', '那么，是什么事呢，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24931, 'zhCN', '你，呃，你把它们带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24933, 'zhCN', '这些是新鲜的，对吧？在太阳底下晒蔫了的东西，它们可不会碰。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24941, 'zhCN', '帕克斯顿已经为大炮装填了发射药，现在只差你临时凑出来的弹药了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24944, 'zhCN', '希望你的绷带够用。自从这些野蛮家伙洗劫了我深爱的吉尔尼斯之后，那些草药的供应就断了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24946, 'zhCN', '嗯，让我看看你弄到了多少。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24948, 'zhCN', '把它们全烧了，$c。烧成灰烬！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24949, 'zhCN', '让我看看你弄到了什么。你没有偷偷给自己藏下一些吧？要知道，没有我，你可找不到买主。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24952, 'zhCN', '哈，你可算来了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24953, 'zhCN', '伙计，我可没听见什么塌方的动静！再试一次！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24954, 'zhCN', '现在正是完成我交给你的那个简单任务的好时候，$n。你说是不是？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24956, 'zhCN', '他死了吗？你拿到他的……头盔了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24957, 'zhCN', '你带够了吗？这些食人魔看起来可不像喜欢小份食物的家伙。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24960, 'zhCN', '别磨磨蹭蹭的。你现在是被遗忘者的一员了，我们对自己人的要求可要高得多。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24961, 'zhCN', '你跟她谈过了吗？她需要有人让她明白真相。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24962, 'zhCN', '啊，你终于来了。很好。我听说还有其他人也从“死亡”中逃脱，正往镇子里来。也许这份顽强的生命力将来还会派上用场。你能获得自由，要感谢希尔瓦娜斯……那就是身心的自由。尽管你依然饱受瘟疫及其后遗症的折磨，但现在的你可以随心所欲地自由来去了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24965, 'zhCN', '怎么了……你的钱花光了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24972, 'zhCN', '说吧，你想要什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24974, 'zhCN', '哦，孤独的痛苦简直让人无法承受！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24975, 'zhCN', '你收集到10个南瓜了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24976, 'zhCN', '我有一种预感，这将是我做得最好的一批，好心的$c。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24977, 'zhCN', '走开，邪恶的亵渎之物！愿圣光保佑我！血色十字军定要将你们从艾泽拉斯铲除……哦，等等。那是给我的食物吗？我好饿……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24979, 'zhCN', '一封信？信上写了什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24980, 'zhCN', '如果你想向黑暗女王证明自己的价值，就去杀死10个血色勇士，$c。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24981, 'zhCN', '我们要像驱赶牲口一样，把血色十字军赶进坟墓里去。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24988, 'zhCN', '你已经弄到五张夜行蝙蝠的皮了吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24990, 'zhCN', '暗犬的血收集齐了吗，$n？时间可不等人！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24994, 'zhCN', '他们给我送来了末日草？  末日草?!', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24995, 'zhCN', '$n，你从鱼人手里弄到那些鳞片了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24996, 'zhCN', '要是我那把心爱的步枪在手，你早就成一具尸体了，$c。等蒸汽坦克旅来救我的时候，有你好受的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24997, 'zhCN', '任务完成了？那些狗东西都被你干掉、吸干体液了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (24998, 'zhCN', '什么事？', 0);
