REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25002, 'zhCN', '什么？我的补给车队被那些冷血的剪刀爪家伙劫了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25004, 'zhCN', '我们和天灾军团的战斗还在继续，$n。做好你该做的事，把那些该死的、没有心智的 $r 赶回瘟疫之地去！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25005, 'zhCN', '你身上有天灾的腐臭味，$n。你想找什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25009, 'zhCN', '你回来了，可任务还没完成。难道几个人类的干扰就让“黑暗女士”的计划顺水推舟了吗？还是说你愿意听从职责的召唤，去把不远处的血色匪帮斩尽杀绝！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25013, 'zhCN', '$n，你拿到恶性夜行蛛的毒液了吗？那是我做实验还差的最后一份材料。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25014, 'zhCN', '发现什么了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25015, 'zhCN', '我得提醒你，你八成需要一把开山刀才能劈开这片乱麻。
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25020, 'zhCN', '石板带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25021, 'zhCN', '你自己没偷喝吧？我要的是全部……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25024, 'zhCN', '还有更多联盟伞兵等着收拾，我们要逃离这座岛，就得先把他们打发掉，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25025, 'zhCN', '灵魂们说对了吗，老兄？东西带来了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25026, 'zhCN', '东西带来了吗，老兄？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25027, 'zhCN', '难怪部落讨厌这些讨厌的小东西。三齿怪你接手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25028, 'zhCN', '我很忙，$c。这失控的疯长威胁着整片大陆。有什么消息吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25029, 'zhCN', '阿加曼德家的遗骸带来了吗？那些被诅咒的畜生终于被消灭了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25030, 'zhCN', '嗯嗯……看看这是谁来了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25037, 'zhCN', '大海能给的珍馐不多，新鲜的爬行者肉算一样。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25038, 'zhCN', '那个没用的憎恶哪儿去了？要么把我要的东西拿来，要么就滚出去找到它再说。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25042, 'zhCN', '<特罗利舔着嘴唇，口水都快憋不住了。>
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25044, 'zhCN', '獠牙鼻！他死了吗？外面什么情况？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25048, 'zhCN', '你带了一大堆箱子来吗？让我瞧瞧！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25054, 'zhCN', '你该不会想私藏几个吧，小傻瓜！这副护目镜能看穿你的背包，还有你的护甲。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25055, 'zhCN', '元素被你驯服了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25056, 'zhCN', '让我看看……皮革够数了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25057, 'zhCN', '塔纳乔那边的情况控制住了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25059, 'zhCN', '你去搜过那片废墟了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25062, 'zhCN', '找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25063, 'zhCN', '但愿你那场海龟屠杀没把它弄坏。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25065, 'zhCN', '箱子里的东西可得轻拿轻放。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25066, 'zhCN', '你跑回来干什么？上去把他们打下来！', 0);
