REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25219, 'zhCN', '我知道，这活不怎么样，可面对那副龟壳，你能忍住不好奇吗？那么大的一副壳，里面肯定另有玄机。', 0);
