REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25263, 'zhCN', '最诚挚的问候，$c。今天我能为我 $r 的兄弟做点什么？', 0);
