REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25270, 'zhCN', '这些野兽曾经也是人类，却在暮光之锤的影响下变成了没有心智的野兽。别犹豫，把它们全杀了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25271, 'zhCN', '像我这样的狼人都是被戈德林的故事吸引而来的——他的力量与智慧。可这些破坏分子崇拜的完全是狼神的另一面。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25272, 'zhCN', '你的勇气激励着众人，$c。告诉我你的名字。', 0);
