REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25285, 'zhCN', '那些弹射系统总得有人来测试……话说回来，这主意倒也不赖……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25287, 'zhCN', '你是来替托比·齐吉尔发表演讲的吗？', 0);
