REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25353, 'zhCN', '又见面了，$c。你在身后留下的是恐惧与混乱的轨迹。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25355, 'zhCN', '又见面了，$c。你打得很棒！你在身后留下的是恐惧与混乱的轨迹。$B$B<洛戈什满怀期待地打量着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25358, 'zhCN', '补给弄到手了吗，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25361, 'zhCN', '小精灵龙被惹急了可是很危险的，$c，跟它们打交道要小心。更要当心附近的暗夜精灵——那帮烦人的家伙也总在森林里转悠。凑够翅膀了就告诉我，我一定好好酬谢你！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25362, 'zhCN', '$c，把我的话当真：恐怖图腾氏族是邪恶的。如果你查到了他们的行踪，那就该由你回去，赶在他们踏进我们的土地、烧毁我们的村庄、掠夺我们的家园之前，给他们氏族迎头一击。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25363, 'zhCN', '我们把他们打退了，他们却还在进攻！一定有谁在驱使他们发狂……哦，你回来了啊，$n？偿金要的鬃毛带够了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25366, 'zhCN', '欢迎回来，$n——找到能证明豺狼人图谋的确凿证据了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25367, 'zhCN', '狩猎进行得如何，$n？你是来报告战果的吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25369, 'zhCN', '刺鞭怪被你放倒了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25372, 'zhCN', '我已是一筹莫展了，$n！艾西娜一直沉默不语。$B$B你发现什么了吗？这是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25377, 'zhCN', '这把锁虽然结了些垢，但应该还能用。', 0);
