REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25452, 'zhCN', '十张厚雪人皮凑齐了吗？我的皮货无与伦比，你带皮来，我就分你几件好东西。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25453, 'zhCN', '狂暴疤痕雪人还在那儿吗？皮弄到了吗？', 0);
