REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25466, 'zhCN', '元素核心的技术细节我就不多啰嗦了，直接说重点：完成这项重要任务，就有丰厚的金币和奖励等着你。怎么样，完工了吗？', 0);
