REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25473, 'zhCN', '我们的卡加可乐还不够！我发誓，要是不能先宰了丹普威克，我非开除他不可！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (25475, 'zhCN', '你好像挖出了一堆……机器小鸡的残骸？蛋壳里传出的声音又劈啪作响起来：$B$B“好极了，干得漂亮！这确实是我的寻的机器人，不过我的传感器显示，它得先进行助推启动，才能飞回藏宝海湾修理。把信标放进机器里就行——剩下的事信标会搞定！”', 0);
