REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26172, 'zhCN', '我快饿疯了！你要是不快点，我真可能把我们的试剂给喝了。', 0);
