REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26180, 'zhCN', '一想到风险投资公司为了利润甘愿对我们犯下的暴行，我就怒火中烧。', 0);
