REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26235, 'zhCN', '口粮找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26241, 'zhCN', '材料一齐，饭立马就好！快点！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26244, 'zhCN', '你回来了，$n。', 0);
