REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26256, 'zhCN', '$n，要重铸世界之柱，我们得抓紧了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26259, 'zhCN', '你回来了，$n。血带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26264, 'zhCN', '找到受辐射的侏儒的遗物了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26266, 'zhCN', '下午好，先生。请问有何吩咐？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26268, 'zhCN', '找到几个货箱？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26269, 'zhCN', '找到了吗？我可不想把一本几乎完工的书还给赫米特。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26275, 'zhCN', '我看它们没什么挑战性，老兄，可你要是腿脚不利索，它们照样会抓破你的脚踝。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26281, 'zhCN', '我的部队里没有怜悯的份。巨魔可以在别处找吃的。丛林这么大。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26283, 'zhCN', '怎么样？找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26285, 'zhCN', '那么，我失踪的补给找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26286, 'zhCN', '进攻命令找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26295, 'zhCN', '顺利吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26296, 'zhCN', '红头巾？！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26298, 'zhCN', '$c。让我看看你有没有把血顶部族当成猎物。把战利品拿给我看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26299, 'zhCN', '$n，我担心我们酋长的儿子。缩头带来了吗？让我查验一下。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26300, 'zhCN', '锅里泛绿的汤汁冒着泡。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26301, 'zhCN', '我等着那些头骨……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26303, 'zhCN', '你好，$n。灵魂们都在称颂你的英勇，可它们没有讲过你对付迈佐斯的任务。眼睛在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26305, 'zhCN', '$n，金威利告诉我你出发去抓耶尼库了。是真的吗？他在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26309, 'zhCN', '靠近那些大锅时当心点，$c。恶枝部族不会轻易让人拿走他们的好东西。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26310, 'zhCN', '你弄到多少？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26311, 'zhCN', '啊，$c，你回来了。有什么发现？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26313, 'zhCN', '我们从来没跟元素领主称兄道弟过，但混乱中我们仍能信任一点安全感。只要它们没有组织，我们就没什么可怕的。$B$B如果石母真的在召集大地与我们为敌，我们要怕的可就多了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26325, 'zhCN', '你找到了几个？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26329, 'zhCN', '欢迎回来，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26330, 'zhCN', '甘祖拉……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26332, 'zhCN', '<巨大的巨魔头骨在大锅里打着转。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26334, 'zhCN', '我只想要那只迅猛龙，$r。把它给我，巨魔就能活命。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26343, 'zhCN', '我的装备全都就绪了，$n，只差那些皮了。我们可不能让里德沃克斯久等，这是肯定的。$b$b让工会首席发明家不痛快，对谁都没好处。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26344, 'zhCN', '德兹里克卓越牌皮靴，工艺精湛，百分之百优质咸水鳄皮靴。无出其右！$b$b再生动的广告词也不过如此，对吧？$b$b不过，除非你把那些皮带来，对吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26345, 'zhCN', '我在哪儿读到过，老年鳄鱼正在慢慢灭绝……对我的生意可不是好消息，对吧？$b$b不管怎样，希望你把老年钳嘴鳄的皮给我带来了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26347, 'zhCN', '没有粘液，火就烧不了多久，$n。我们以前也用油，可那东西很难搞到！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26349, 'zhCN', '那个叫浊眼的老家伙被你干掉了吗？有人看见他在西部的海岸线一带游荡。等那头肮脏的野兽死了再来见我。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26351, 'zhCN', '那只叫奥甘娜卡的迅猛龙，还是你的朋友。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26352, 'zhCN', '风险投资公司在荆棘谷犯下的罪行不可饶恕。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26354, 'zhCN', '这个看起来就是对的桶。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26355, 'zhCN', '空壶里插着一条线索。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26356, 'zhCN', '桑德斯的失落宝藏就在前方！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26361, 'zhCN', '斯穆特是个好工程师。要是减速卡尺装歪了，三十码外一台萨姆弗朗格就能要人命。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26363, 'zhCN', '找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26366, 'zhCN', '拿出来看看！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26368, 'zhCN', '毒液……带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26369, 'zhCN', '一定要搜她的尸体。我可不想恶枝部族设下的陷阱随着他们的死一起被藏起来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26380, 'zhCN', '欢迎，客人。你是来旅店休息的，还是需要一个新的炉石？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26381, 'zhCN', '要是那块石板是个幌子，我可不会高兴。眼睛找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26382, 'zhCN', '希望你带够了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26389, 'zhCN', '横冲直撞的兽人杀掉了吗？', 0);
