REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26395, 'zhCN', '额头上是汗吗，$glad:ma''am;？你跑得太多了。下次坐狮鹫吧！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26396, 'zhCN', '你从暴风城回来了？奥斯里克把护甲送来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26397, 'zhCN', '是什么让你来寻求部落大酋长的接见，$r？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26399, 'zhCN', '为什么这些无价古董总是被食人魔先找到？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26400, 'zhCN', '箱子打开了吗？我等不及想看看里面是什么了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26401, 'zhCN', '你回来了……他却没有……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26403, 'zhCN', '那些水晶带来了吗？？我需要它们！！我是说……我需要知道邪恶的风险投资公司在荆棘谷节节败退。因为你知道，我们老实人也要混口饭吃嘛！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26406, 'zhCN', '尖牙拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26407, 'zhCN', '你说这是一只手？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26410, 'zhCN', '树脂用不了多少。不过那些岩穴撕魂者相当危险。', 0);
