REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26420, 'zhCN', '诱饵起作用了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26427, 'zhCN', '我要的东西带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26428, 'zhCN', '把他们全杀了，把首级带回来给我！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26433, 'zhCN', '明净圣水？就在这里吗！？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26434, 'zhCN', '试剂一定要选最松软的，$n。粗糙的试剂可不行。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26435, 'zhCN', '怎么了，$r？我很忙。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26437, 'zhCN', '我拜托你的事办了吗？水晶带回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26440, 'zhCN', '<小石满怀期待地抬头看着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26442, 'zhCN', '看来你躲过了那些鲨鱼。陷阱里有龙虾吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26443, 'zhCN', '你手里拿着什么，先生？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26445, 'zhCN', '我们的暗夜精灵斥候报告说，进攻的准备已近完成。那些恐惧魔王必须尽快除掉，$n！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26447, 'zhCN', '你手里拿着什么，斥候？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26449, 'zhCN', '那些恐惧魔王必须尽快除掉，$n！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26450, 'zhCN', '拿出来看看！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26454, 'zhCN', '尼莫斯建筑师说过，你可能会带来一些从被玷污的萨提纳尔打捞来的木头。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26455, 'zhCN', '$n，你感觉到了吗，风中那丝腐化的气息？如果我们坐视不管，它会继续蔓延。所以我才寻找艾露恩的圣杯。找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26456, 'zhCN', '你手里拿着什么，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26464, 'zhCN', '啊，欢迎回来，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26465, 'zhCN', '$n，雕像找到很多了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26466, 'zhCN', '据说佐拉姆之戒能打开城里的任何一把锁。在你手上吗，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26468, 'zhCN', '找到她们了吗？阿妮莉娅说了什么？她在哪儿？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26469, 'zhCN', '求你，帮我为阿妮莉娅报仇。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26473, 'zhCN', '$n，巴斯兰的发丝收集齐了吗？孩子的病情每小时都在恶化……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26474, 'zhCN', '我必须道歉，我没时间多聊。我的孩子蕾拉拉病危了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26475, 'zhCN', '$n，湖底的遗骸找到了吗？眼泪在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26476, 'zhCN', '你好。最近怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26477, 'zhCN', '树人被腐化，让我难过极了。我多想再多帮帮它们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26478, 'zhCN', '法杖的最后一块找到了吗，$n？我的手法灵吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26479, 'zhCN', '怎么了，$n？进展如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26481, 'zhCN', '我的朋友，兰被你杀了？要把我的族人从奴役中解救出来，就必须拿他的头骨。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26482, 'zhCN', '你回来了，$n。法杖顶端装的是什么？头骨？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26485, 'zhCN', '砂囊带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26486, 'zhCN', '十二个左右就够了，对吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26487, 'zhCN', '让我看看……我们得为自然远足买几支猎枪，去钻油平台一日游要几条划艇，还有……哦，你已经回来了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26488, 'zhCN', '我的挂坠盒找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26489, 'zhCN', '让我看看……我们得为自然远足买几支猎枪，去钻油平台一日游要几条划艇，还有……哦，嗨，老板 $n。你已经回来了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26490, 'zhCN', '好啊，东西在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26492, 'zhCN', '货箱弄到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26493, 'zhCN', '希望你是按我们讨论的萃取步骤操作的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26494, 'zhCN', '嘿，那是杂志上说的那种东西吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26495, 'zhCN', '愿意解释一下吗，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26502, 'zhCN', '你算什么东西？血肉的败笔？你简直就是个被诅咒的东西！要么有点用处，要么就滚出我的防线！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26503, 'zhCN', '豺狼人的作战图找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26505, 'zhCN', '我的单片眼镜放哪儿了？！科纳彻，是你吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26506, 'zhCN', '我的原料找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26507, 'zhCN', '<小石开始抬头看你，眼睛微微发光，越来越圆，越来越大。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26508, 'zhCN', '你好。我想我的项链了。是爸爸给我的。爸爸说湖里有怪物。你揍过怪物吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26509, 'zhCN', '肚腩怪还在作乱吗，还是说你已经一劳永逸地帮湖区除了害？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26510, 'zhCN', '侏儒通讯器找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26513, 'zhCN', '补给找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26514, 'zhCN', '项圈找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26517, 'zhCN', '找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26518, 'zhCN', '拿出来看看！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26523, 'zhCN', '让我看看你有什么。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26524, 'zhCN', '靠近那些大锅时当心点，$c。恶枝部族可不会轻易交出来！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26526, 'zhCN', '一定要搜她的尸体。我可不想恶枝部族设下的陷阱随着他们的死一起被藏起来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26528, 'zhCN', '石板上的话应验了吗？眼睛找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26529, 'zhCN', '尖牙拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26530, 'zhCN', '东西带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26533, 'zhCN', '太好了……你还没变成亡灵。很好。哦，嗯……没什么。只是……那确实有风险。我忘记提醒你了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26535, 'zhCN', '他用了闪光草吗？我猜他用了闪光草。$B$B不对等等……琥珀种子！肯定是琥珀种子。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26536, 'zhCN', '找到那道瀑布了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26540, 'zhCN', '你为我们伤员带来希望了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26543, 'zhCN', '蛤蜊找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26544, 'zhCN', '查明什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26545, 'zhCN', '黑石的入侵计划在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26549, 'zhCN', '$N，听说你要去跟我们的“大酋长”谈加入你们部落的事。$B$B当心点，$c。$B$B事成之后来见我……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26556, 'zhCN', '钓上几条标本了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26557, 'zhCN', '那只眼睛当诱饵管用吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26560, 'zhCN', '梅斯纳！该死，见到熟脸真好。放我出去！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26562, 'zhCN', '瞧瞧！队员全都在了……就差基尚。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26564, 'zhCN', '怎么样？我可没一整天耗着。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26569, 'zhCN', '望远镜找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26571, 'zhCN', '墨敦和霍默克被干掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26572, 'zhCN', '下面情况怎么样？尾巴和石头鱼有收获吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26573, 'zhCN', '头带和护符定位到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26585, 'zhCN', '我等着你的证据，$r……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26587, 'zhCN', '笼子的钥匙拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26588, 'zhCN', '巨型狗鱼钓到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26590, 'zhCN', '明净圣水？就在这里吗！？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26592, 'zhCN', '那些是我看到的宝石吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26593, 'zhCN', '喂！我不喜欢你那眼神，$gmister:lady;。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26594, 'zhCN', '这边这边，$n。谢奇的报酬拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26595, 'zhCN', '$n，那些欠债人找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26597, 'zhCN', '……妈妈？……好冷…………正在坠入扭曲虚空……抱抱我，妈妈……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26598, 'zhCN', '巫医安巴瓜知道野蛮的莫克喜欢什么。对，对！我和灵魂说话，把他叫来，我能做到。可其他的大猩猩兽也爱听灵魂说话。你保护好巫医安巴瓜，我就把他叫到你面前。巫医安巴瓜要先要点东西。你带一根猩猩尖牙来，我就开始跟灵魂说话！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26599, 'zhCN', '你好啊，$n！找到戈拉什了吗？那箱子是我的心头好，里面有个暗格，装着我最珍贵的宝贝！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26600, 'zhCN', '我们需要大量食物，$n。这里的方针是重数量，轻质量。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26605, 'zhCN', '一想到穆克拉打算拿我怎么处置，我就不寒而栗。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26606, 'zhCN', '感谢祖先，总算有人来救我了。能放我走的钥匙在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26607, 'zhCN', '又是你？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26612, 'zhCN', '你好啊，$n。南边血帆营地的消息如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26613, 'zhCN', '货找到了吗，伙计？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26614, 'zhCN', '你好啊，老弟！我是看不见，可半个码头外我就闻得出你。我真需要把我的眼睛拿回来。船长要是发现我的眼珠子落在一帮脏血帆海盗手里，非把我吊在龙骨下拖死不可。一个看不见的瞭望员有什么用？桅杆瞭望台曾是我的家……没了这双眼，我顶多能去刷刷舱底。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26617, 'zhCN', '你手里拿着什么，$r？让我看看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26620, 'zhCN', '五块狼排带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26623, 'zhCN', '你好，$n。大块肉给我弄来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26625, 'zhCN', '他死了吗？木棍拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26629, 'zhCN', '这是菲拉隆亲自特批的。说牛魔人风险太大。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26630, 'zhCN', '你应该明白，大多数牛头人都会认为这是奇耻大辱。我却觉得……挺好笑。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26631, 'zhCN', '证件带齐了吧，水手。我可不乐意把你送回扬西那儿。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26634, 'zhCN', '$r，这种完全可以预防的病，我见它害死的够多了。我们需要那些酸橙。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26635, 'zhCN', '告诉你，我也不是生来就当水手的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26636, 'zhCN', '树叶和便便——我需要的就是这些。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26637, 'zhCN', '腺体找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26640, 'zhCN', '他们把布鲁贝克抓走了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26641, 'zhCN', '蛋带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26652, 'zhCN', '<啜泣> 哦求你了，别看我！这双眼睛是我亲手挖出来的，可我还是能感觉到你的目光！$B$B我太难看了！难看极了！求你，把视线移开！！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26654, 'zhCN', '我感觉你见过盲眼玛丽。我的梳子……在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26655, 'zhCN', '我得用幽灵丝线沿着门和窗户布置起来，挡住不速之魂。帮我弄来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26658, 'zhCN', '找到木槌了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26661, 'zhCN', '你好，$n。给我的腐烂花弄到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26667, 'zhCN', '听着，$gsir:miss;，我可真不想惹麻烦……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26669, 'zhCN', '我看你完好无损地回来了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26670, 'zhCN', '我说过，$n，不值得追查……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26671, 'zhCN', '你回来了！查到我哥哥的消息了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26672, 'zhCN', '什么黑暗的低语把你引到了我的门前，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26676, 'zhCN', '我得靠那僵尸汁熬过这些又冷又黑的夜晚。帮我弄来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26677, 'zhCN', '鸦风山那边肯定也有不少肋骨，不过深更半夜，你最好别走那么远……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26679, 'zhCN', '猜猜你不在的时候谁来过了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26680, 'zhCN', '我的箱子在你手上吗？在的话……求你快给我！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26681, 'zhCN', '一封信？这是怎么回事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26684, 'zhCN', '我把我们观星机的雏形给科格看了。他大为赞叹。你有没有碰巧找到反射装置？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26685, 'zhCN', '你说服扎尔武把单片眼镜借给我们的实验了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26691, 'zhCN', '嗯，什么事？长话短说，我有要紧事要办。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26693, 'zhCN', '我听得清清楚楚，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26695, 'zhCN', '你还活着？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26706, 'zhCN', '值得一冒的险，只有那些通向辉煌胜利的险。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26707, 'zhCN', '尸草带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26719, 'zhCN', '什么风把您吹到这边来了，我尊敬的 $gsir:lady;？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26721, 'zhCN', '拿到了吗？快告诉我你拿到了……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26729, 'zhCN', '怎么了，$n？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26730, 'zhCN', '盐呢？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26731, 'zhCN', '我迫不及待想看结果了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26732, 'zhCN', '空闲的时候，我也算是半个炼金师呢。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26733, 'zhCN', '这药液有点不对劲，$n。虽然分析还没完成，但我能感觉到。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26734, 'zhCN', '拿那东西千万小心，$n。我们还不知道它是什么。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26735, 'zhCN', '你找到了什么，$n？', 0);
