REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26747, 'zhCN', '甘祖拉是个暴徒加暴君。我有个预感，这头巨魔会不一样。巨魔魔法比我想的容易嘛！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26748, 'zhCN', '我只想要那只迅猛龙，$r。把它给我，侏儒就能活命。', 0);
