REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26769, 'zhCN', '欢迎，$c。刚从棘齿城坐船过来？有什么消息吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26772, 'zhCN', '那只叫奥甘娜卡的迅猛龙，还是你的朋友。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26774, 'zhCN', '超大的法术需要超大的脑子，没错。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26781, 'zhCN', '眼睛在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26782, 'zhCN', '为什么这些无价古董总是被食人魔先找到？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26783, 'zhCN', '为什么这些无价古董总是被食人魔先找到？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26784, 'zhCN', '希望激流河里的搏斗没太危险。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26787, 'zhCN', '拿到了吗？拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26788, 'zhCN', '泥带了吗？新墙的修建已经动工了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26795, 'zhCN', '$n，你要是拿他没办法，我不怪你。我们好几名最强的守望者都折在了莫拉迪姆手里。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26797, 'zhCN', '别管我……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26799, 'zhCN', '要是连最弱小、最没脑子的生物都杀不了，你在这新生命里走不了多远，$n。带着战果再来见我。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26800, 'zhCN', '尸首搜罗到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26801, 'zhCN', '在这任务里磨蹭的人，到头来只会像村里那些倒下的兄弟姐妹一样漫无目的地游荡。希望你比他们强点，好吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26802, 'zhCN', '在我给你弄到盔甲之前，可千方百计别让自己受伤。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26806, 'zhCN', '准备好回奥格瑞玛了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26807, 'zhCN', '那些报告带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26808, 'zhCN', '愿意解释一下吗，$c？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26815, 'zhCN', '太好了……你还没变成亡灵。很好。$b$b哦，嗯……没什么。只是……那确实有风险。我忘记提醒你了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26816, 'zhCN', '他用了闪光草吗？我猜他用了闪光草。$b$b不对等等……琥珀种子！肯定是琥珀种子。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26817, 'zhCN', '<你走近时，达斯克热切地盯着你的背包。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26818, 'zhCN', '哦哦……但愿它们软软的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26819, 'zhCN', '欢迎回来！', 0);
