REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26842, 'zhCN', '那么，耳朵给我带了些吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26845, 'zhCN', '下面那位该不会是茉艾拉吧？奇迹偶尔也会发生。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26855, 'zhCN', '你好，$n。有我朋友希尔德维的消息吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26858, 'zhCN', '要是塔拉加曼死了，把他的心脏拿给我看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26860, 'zhCN', '我都准备好下厨了，熊肉给我带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26862, 'zhCN', '绑带带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26863, 'zhCN', '$n，那批矿工补给带来了吗？', 0);
