REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26871, 'zhCN', '你活着。很好。$B$B宝石带在身上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26872, 'zhCN', '那些野兽你杀了多少？', 0);
