REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26875, 'zhCN', '我们绝不能让仪式被打断。他们需要你去后舱帮忙——请快一点。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26876, 'zhCN', '$n！你回来了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26882, 'zhCN', '很高兴再见到你，$n。有什么消息吗？$B$B突袭顺利吗？找到赛尔瑞德了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26883, 'zhCN', '黑暗深渊曾是一座古老的暗夜精灵神庙，里面有一口极为强大的月井。谁知道暮光之锤在那儿如今酿着什么邪恶。$b$b肃清神庙有进展了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26884, 'zhCN', '等有了足够的研究样本，我真正的工作就能开始。有了黑暗深渊里萨特和娜迦被腐化的脑干，我就能尝试找出两种变异之间的关联。$b$b也许凭这些知识，我们能阻止血精灵在畸变与邪恶的深渊里越陷越深。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26885, 'zhCN', '这任务可不轻松，我的朋友。$B$B但如果你把手稿带给我，$n……你的酬劳会很丰厚，我们也能更清楚地了解暮光之锤和娜迦到底在搞什么。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26887, 'zhCN', '齿料带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26890, 'zhCN', '水晶找得怎么样了，$n？你觉得它们能做成制服娜迦的东西吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26891, 'zhCN', '深渊之核定位到了吗？没有它，我们完全摸不清暮光之锤在下面到底搞什么。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26899, 'zhCN', '复仇……报酬……', 0);
