REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26928, 'zhCN', '你现在可真是臭气熏天！我猜是那些鱼人闹的，不过还真难说。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26929, 'zhCN', '所以你弄到那些鳄鱼皮了，还是我记错了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26934, 'zhCN', '动物组织比植物组织留病留得久多了，不是吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26951, 'zhCN', '$c，面具都收齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26961, 'zhCN', '那些神像都在吗？我们必须研究它们，然后把发现汇报给铁炉堡！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26966, 'zhCN', '印记和审判都练过了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26992, 'zhCN', '我要的凶残末日草收集齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26993, 'zhCN', '我可不想再在一座挤满仇恨亡灵狂热分子的修道院里多待一天。你肯定能理解。书不在手上就别跟我说话。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26995, 'zhCN', '记住，我们研发的新型枯萎剂只能用干净的野兽内脏。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26996, 'zhCN', '<多米尼克凝视着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26998, 'zhCN', '晨曦群岛的秽鳍鱼人消灭了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (26999, 'zhCN', '等动物们都痊愈了，我们在这里的任务也就差不多完成了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27004, 'zhCN', '这些图纸是解开一切的关键。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27005, 'zhCN', '这些图纸是解开一切的关键。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27011, 'zhCN', '有些老伐木工告诉我，红松豺狼人几年前在这一带住过，瘟疫来了之后就搬走了。不过这可不构成他们偷窃的理由。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27012, 'zhCN', '我不想因为一位母亲的担忧，就下令对豺狼人搞种族灭绝。我只是想在自己的家里有安全感。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27014, 'zhCN', '很高兴认识你，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27015, 'zhCN', '很高兴认识你，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27017, 'zhCN', '我知道不该指望你来满足一个怀旧老人的心愿，$n。不过，要是你碰巧路过那片地方……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27019, 'zhCN', '我对政治不感冒；你效忠部落还是联盟，我不关心。我更关心铲除对所有种族的直接威胁……而眼前就有一个巨大的威胁。如果你愿意做一名真正的全人民英雄，就把我给你的誓约石交还给我，作为承诺的信物。我……不是本地人；对我的族人来说，誓约石是缔结盟约的重要信物。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27025, 'zhCN', '拿稳了，别出岔子！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27028, 'zhCN', '那些黄蜂怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27029, 'zhCN', '獠牙带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27030, 'zhCN', '给我带了什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27031, 'zhCN', '只用最好的羽毛！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27036, 'zhCN', '啊，$n！这么快就回来了？又去打猎了吧？就算碰了钉子也别担心，长远看这会让你更强！$b$b……反正你也不会更糟了……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27037, 'zhCN', '干得漂亮，$n！好好教训了他！来，把头给我，我来处理。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27038, 'zhCN', '啊这？我的零件。在哪儿呢？没有零件可造不了坦克！要是你硬造，那也小得很。而且多半没什么内用。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27047, 'zhCN', '对我们来说，磨钻石是最珍贵的材料之一，尤其因为我们靠自己根本到不了那些矿床。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27048, 'zhCN', '要炸了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27051, 'zhCN', '我交代的事办了吗？他们手里残余的促长剂，我们必须一网打尽。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27053, 'zhCN', '大锅的检修板还锁得死死的。要打开它，你得先找到钥匙。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (27054, 'zhCN', '你翻看玛莉西娅随身带着的文件……', 0);
