REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28215, 'zhCN', '要是你现在就从背包里掏出一大堆元素熔卷，那你可要把我这只侏儒乐坏了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28216, 'zhCN', '这些年，老洪堡特一直觉得最大的麻烦就是山脊上那帮格罗普古特食人魔。然后暮光之锤来了。眨眼间，他们把整座山谷点得像生日蛋糕一样亮。没人性的东西。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28223, 'zhCN', '看守死了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28226, 'zhCN', '这些魔像可是我们自己造的，知道吧。加点机械手艺，再加点元素魔法……成果不赖，依我看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28231, 'zhCN', '为了小闪闪！', 0);
