REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28341, 'zhCN', '精华务必小心对待。它有多强大，就有多致命。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28342, 'zhCN', '自己杀掉的猎物，也记得把该捡的捡干净。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28343, 'zhCN', '绝不能让黑铁矮人和暮光之锤结盟。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28350, 'zhCN', '$n，装满我这桶的量凑够了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28354, 'zhCN', '泥鼻兽找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28359, 'zhCN', '核心绝不能被带到碎痕谷去。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28364, 'zhCN', '钥匙拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28366, 'zhCN', '武器带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28376, 'zhCN', '那头龙被你放倒了！？了不起！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28386, 'zhCN', '我说对了吗？你找到了几个？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28393, 'zhCN', '绝不能让黑铁矮人和暮光之锤结盟。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28394, 'zhCN', '绝不能让那些魔像反过来对付我们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28396, 'zhCN', '你已经在我这儿证明了自己，但我部族里多疑的兄弟们，可能还需要你继续证明。为此，我可以继续帮你。$B$B一些死木毛怪戴着一种独特的头饰，可以作为清剿他们的凭据。你每弄到一副这样的头饰，就拔一根羽毛带给我；每凑五根，你在木喉要塞的声望就涨一分。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28398, 'zhCN', '烈焰法师的魔法书夺到手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28399, 'zhCN', '那些缚石找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28400, 'zhCN', '<高阶督军克罗穆什面色凝重。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28408, 'zhCN', '芬妮的羽毛拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28410, 'zhCN', '空袭进行得怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28411, 'zhCN', '$n，粮食的情况怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28415, 'zhCN', '<奥拉留斯抓向空中，攥紧拳头，满怀希望地从指缝间张望。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28417, 'zhCN', '希望我们还没太迟。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28419, 'zhCN', '这么快就回来了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28420, 'zhCN', '让我瞧瞧那些皮子。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28421, 'zhCN', '那些黑曜石元素你可要当心。它们最爱冷不防地偷袭人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28423, 'zhCN', '看看你是不是全弄齐了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28425, 'zhCN', '看起来你把戈尔齐基料理妥当了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28436, 'zhCN', '欢迎回来，士兵。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28443, 'zhCN', '黑曜石元素的灰烬格外漆黑——正好是我们需要的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28444, 'zhCN', '火灵弱得很，可它们成群行动。当心。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28445, 'zhCN', '外面有收获吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28448, 'zhCN', '你来了，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28450, 'zhCN', '手里拿着什么，士兵？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28451, 'zhCN', '什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28452, 'zhCN', '我没空陪你玩游戏，蠢货。滚出我的视线。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28457, 'zhCN', '绝不能让黑铁矮人和暮光之锤结盟。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28458, 'zhCN', '烈焰法师的魔法书夺到手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28459, 'zhCN', '那些缚石找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28461, 'zhCN', '绝不能让那些魔像反过来对付我们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28467, 'zhCN', '$n，希望你找到了点什么。落雪毛怪越来越嚣张了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28469, 'zhCN', '等落雪毛怪没了火酒喝，咱们再看看会怎样！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28471, 'zhCN', '那么，$n，这是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28472, 'zhCN', '$c，你带着的是什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28483, 'zhCN', '很高兴再次见到你，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28484, 'zhCN', '给我弄些雪人的心脏来，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28485, 'zhCN', '尤提姆斯必须死！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28486, 'zhCN', '你好，$n！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28487, 'zhCN', '我在这儿几乎是一丝不挂啊，$n。帮帮忙，好吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28488, 'zhCN', '这些水晶价值连城，对戈尔西克来说尤其如此。要是能得到一颗，我就能拿捏他。我希望如此。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28489, 'zhCN', '我需要雄鹿肉！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28491, 'zhCN', '怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28498, 'zhCN', '$n，它们找到了吗？还有救吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28500, 'zhCN', '$n，法典找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28518, 'zhCN', '迈尼乌斯是一位强大的法师，一位可敬的精灵。他的灵魂不该遭此屈辱的命运。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28522, 'zhCN', '$n，你对木喉一族所做的一切，我们感激不尽。你继续努力，必将赢得我部族的信任与尊重。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28524, 'zhCN', '欢迎来到温泉。你手里拿着什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28529, 'zhCN', '$c，我能为你做点什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28530, 'zhCN', '找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28537, 'zhCN', '那个暗影找到了吗？查得出它的来历吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28540, 'zhCN', '熊弄到了？让我瞧瞧那头熊。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28583, 'zhCN', '我认得你！我们坐同一艘飞艇进来的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28593, 'zhCN', '克拉兹等着呢。麻利点。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28595, 'zhCN', '告诉我你办成了？你总能办成的。让我看看我的宝贝！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28597, 'zhCN', '我还需要更多火药！给我弄更多火药！多多多！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28598, 'zhCN', '没有炸弹解决不了的问题。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28602, 'zhCN', '搜查进行得如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28608, 'zhCN', '东西就放在暗影墓地里。我记得是落在工作台上了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28610, 'zhCN', '碎石弄到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28618, 'zhCN', '哦，又是你。那块巨石呢？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28625, 'zhCN', '把木材拿给我看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28626, 'zhCN', '快砍快砍！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28628, 'zhCN', '啊，你回来了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28629, 'zhCN', '这儿有一大摊活儿等我开工呢。兽皮请尽快给我带来！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28631, 'zhCN', '都完美吗？最好全都完美！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28632, 'zhCN', '哦，你回来了！雪人怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28633, 'zhCN', '哦，你看。$b$b快瞧瞧那个！？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28658, 'zhCN', '那片沼泽清剿完了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28661, 'zhCN', '大法师除掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28662, 'zhCN', '日记找回来了吗？报告说，那些地方里里外外都见过它们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28664, 'zhCN', '焰喉犬死了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28665, 'zhCN', '镣铐找到很多吗？报告说那底下到处都是。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28669, 'zhCN', '看守死了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28670, 'zhCN', '口粮找回来了吗？报告说那底下到处都是。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28680, 'zhCN', '朗姆酒找回来了吗？我倒想试试，可我极度怕水。更别提那条疯鲨了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28684, 'zhCN', '粘稠的丝腺收集到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28685, 'zhCN', '那些步枪有进展吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28687, 'zhCN', '那次“打劫”得手了吗？给我们弄到鱼了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28690, 'zhCN', '股骨找回来了吗？你去试总比我去强。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28692, 'zhCN', '那个磁铁装置真的管用了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28694, 'zhCN', '鬼魂把你吓跑了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28696, 'zhCN', '那些船都收拾掉了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28698, 'zhCN', '炮弹找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28701, 'zhCN', '希望它们完好无损……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28707, 'zhCN', '没料到会在这儿见到生人！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28710, 'zhCN', '你在这儿干什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28713, 'zhCN', '活儿还没干完，$n。把夜刃豹的数量削减下去再来找我。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28714, 'zhCN', '打消我的疑虑吧，$n。把格里奇手下的邪能苔藓带给我。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28715, 'zhCN', '失窃的货找回来之前，我可没法给客人备货。有收获吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28722, 'zhCN', '她绝对想不到！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28724, 'zhCN', '我们亲爱的朋友伤势不妙，就算我已尽力医治。我要的补给带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28726, 'zhCN', '这是个残忍的活儿。要对森林中的生物下这种毒手——不管它们有没有被腐化——我都很痛心。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28727, 'zhCN', '我深爱这些森林。我希望看见腐化被彻底涤净。等我下次回来，我希望是带着轻松的心情。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28729, 'zhCN', '我们近来的历史写满了冲突与暴力。我们要面对的事还有很多。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28730, 'zhCN', '月井里盛着永恒之井的水——那口古老的魔法之井，曾给我们的世界带来无数灾难。德鲁伊善用它的特性，哨兵们把它尊为艾露恩的圣坛，如今连归来的上层精灵也满怀渴望地望着它。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28731, 'zhCN', '你好，$c。今日相逢，有何贵干？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28755, 'zhCN', '白银之手的失落史册，找回了多少？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (28757, 'zhCN', '黑石的战狼被你击退了吗？', 0);
