REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29662, 'zhCN', '空口说我的实力毫无意义。我必须展示给你看。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29663, 'zhCN', '唯有自律，方能求得和谐。唯有和谐，方能作为战士触及真正的潜能。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29664, 'zhCN', '你还没有面对我的资格。先去把火盆点亮。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29666, 'zhCN', '平衡是件精妙的事，极大倚重长者的智慧。长者传授的功课，年轻人未必能一眼看透，所以你必须相信，他们对过往的了解将助我们守住当下。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29667, 'zhCN', '我知道你拿到叶子了。很好。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29677, 'zhCN', '决定不再回到池边，是个艰难的决定。我想舒从来没能真正理解。他还不知道衰老和衰弱是什么滋味。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29685, 'zhCN', '唉，$C，我得承认，我以为再也见不到你了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29686, 'zhCN', '它的精华到手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29691, 'zhCN', '朱槿采到一些吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29692, 'zhCN', '我们还需要更多血色朱槿。这东西永远都不够找。$B$B每五朵扎成一束带给我，我将感激不尽。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29749, 'zhCN', '缚魂术！魔古怎么能被允许重新搞这种恶心的行径？！而现在，我成了一场半失败的召唤的产物……$B$B<那个灵魂气了一会儿，然后转向你。>$B$B现在是什么年代？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29750, 'zhCN', '想不到魔古这些年还在训练灵爪……$B$B瓶子拿到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29751, 'zhCN', '仪式需要的东西找到了吗？没有它们，我们无法引导这些灵魂归位。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29756, 'zhCN', '就算是亡者，也懂得饥饿。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29759, 'zhCN', '找到他了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29761, 'zhCN', '幸会，$c。$B$B只拿到一件小饰品，可当不了角斗场大师。$B$B现在正是真正亮出你本领的时候。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29762, 'zhCN', '我们仍在为倒下的兄弟们哀悼。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29763, 'zhCN', '很高兴看到你无恙，$n。$B$B我们的伤亡已经快扛不住了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29764, 'zhCN', '你摸了一把维库人的斧子？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29765, 'zhCN', '我的货带到了吗，老兄？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29768, 'zhCN', '好了，该警告的都警告过了。木槵子槌带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29769, 'zhCN', '必须把它们杀得一干二净！留一只活口倒也罢了，可要是留下不止一只，我们的麻烦就又要从头开始！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29770, 'zhCN', '自从大地之魂吾古睡着后，土地越来越干，新种子越来越难发芽。我们得守住现有的每一份食物，否则这座岛的日子会越来越难过。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29771, 'zhCN', '我交代的事办了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29777, 'zhCN', '我不想贬低猢狲人的志向——每个种族都要走自己的路。但此刻，他们在伤害我们的身体，也在践踏我们的文化。这条线，不能越。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29781, 'zhCN', '他们居然没拿这些东西把自家村子点了，也算有点出乎我意料。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29783, 'zhCN', '没有心志的坚强，肉体的坚强便无从谈起。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29789, 'zhCN', '休息真好。这些年，生活的重担越压越沉。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29795, 'zhCN', '部落从不临阵退缩。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29797, 'zhCN', '我说的那些箱子找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29801, 'zhCN', '我们的任务完成了吗？$B$B这些圣物制作精巧，一旦持有者被杀便会自解，所以只有手法高超的窃贼才能把它们弄到手。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29802, 'zhCN', '我还指望阿弗拉萨斯特拉兹能给我们找一位称职的 $C 呢。$B$B$n，你带了什么？有解密这条消息的办法吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29803, 'zhCN', '很高兴再见到你，$n。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29807, 'zhCN', '办妥了吗，$C？叛变的国王终于迎来末日了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29811, 'zhCN', '克里克希尔的灵魂从亡灵的诅咒中解脱了吗？护符怎么样了？', 0);
