REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29881, 'zhCN', '每片花瓣落下后，只有一小段时间可以用来调出完美的颜色。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29882, 'zhCN', '毒刺弄到一些了吗？这种事我通常找武僧帮忙，可他们眼下似乎都不在这儿。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29885, 'zhCN', '时间紧迫。我们每耽搁一小时，“白卒”就可能离我们更远。$B$B我要的补给在哪儿？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29887, 'zhCN', '长老是一位水语者。他与水对话，水也会回应他。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29891, 'zhCN', '这片迷雾好像自有主张，不是吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29892, 'zhCN', '在沼泽里留神脚下，我的新朋友。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29893, 'zhCN', '所有食材都收齐了吗？差不多该酿梦酿酒了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29900, 'zhCN', '你……找到卷轴了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29911, 'zhCN', '我是不是闻到了芜菁的味道？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29913, 'zhCN', '它们饿得嗷嗷叫，听得我耳朵难受。$B$B等你当上一阵子养猪人，就能听出饿叫和普通叫的区别了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29914, 'zhCN', '找到了吗？我记得丢了三个。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29915, 'zhCN', '哦……你带着我的……我的羊羔？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29918, 'zhCN', '你不知恐惧。我能在你心里感觉到。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29925, 'zhCN', '啊，又见面了，$n！那么，你收到我的口信了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29928, 'zhCN', '<曼恩双眼圆睁，鼻翼翕张，满怀期待地看着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29933, 'zhCN', '宝贝吃食！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29937, 'zhCN', '你没用徒手碰那玩意儿吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29939, 'zhCN', '到目前为止，还没有什么是炸药解决不了的危机。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29940, 'zhCN', '我爹要他的菜，我可就需要你帮忙了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29942, 'zhCN', '小笨猴把那些咯咯叫的大嘴怪全收拾了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29945, 'zhCN', '调颜料的东西准备好了吗？我先去收了些芜菁。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29948, 'zhCN', '我已经跟那些兔妖说过，别踏进我的地盘。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29951, 'zhCN', '我一见你就知道你是朋友。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29968, 'zhCN', '那些湿漉漉的家伙可得当心……呼哇！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29988, 'zhCN', '找蛋行动进行得如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29992, 'zhCN', '哎哟！哎哟！哎哟！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (29997, 'zhCN', '池水浑浊了。我需要法杖来安抚灵魂，与水对话。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30028, 'zhCN', '这些鸟和小精灵这么闹，我们永远凑不够迷踪酒庄的配额。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30032, 'zhCN', '那片丛林听着就瘆人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30054, 'zhCN', '把那些牙齿带回来，蒙蒙兴许就请你跳几步舞。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30063, 'zhCN', '请小心对待那些面具。稍有疏忽，它们就会试图把你吞掉。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30064, 'zhCN', '经书怎么样？没有破损吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30065, 'zhCN', '箭矢找到一些了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30072, 'zhCN', '所有东西都找到了吗？我们的工序都仔细看过了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30076, 'zhCN', '这回肯定妙极了。就跟酿酒一样，只不过我把水换成了水灵肉。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30080, 'zhCN', '<伊墨长叹一声。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30081, 'zhCN', '真不敢相信念念这么晚才想到这一点。这可是唯一能毁掉他一整天的东西……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30088, 'zhCN', '<念念正埋头在树皮上刻着什么。>$B$B这回肯定妙极了，你就瞧好吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30097, 'zhCN', '诺兹多姆在分秒必争地行动。这可不是他的一贯做派。$B$B换作平时，我会把档案整理得更完备。但事到如今，我们只能挑挑拣拣，择要记录……并且雇用你这样的佣兵来帮忙。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30107, 'zhCN', '你收集了多少颗宝石？$B$B我父亲的爪牙们跟他一样扭曲吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30109, 'zhCN', '娜丽丝。死了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30113, 'zhCN', '啊，你回来了！我再也感觉不到娜丽丝的气息了。她死了吗？还是说，她把我们两个都骗过去了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30116, 'zhCN', '晶簇你弄到多少串了？$B$B你们种族的坚韧一直让我深受鼓舞！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30117, 'zhCN', '你好，$c。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30118, 'zhCN', '我父亲怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30123, 'zhCN', '连丛林的空气里都弥漫着危险。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30128, 'zhCN', '蕾扎痛苦万分。如今能救她和孩子的，只有超越我的力量。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30129, 'zhCN', '魔古一族曾以帝王之姿君临天下，奴役他们遇到的每一个种族。$B$B看来这些魔古还想重温旧梦。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30130, 'zhCN', '我挨过拳头，挨过刀子，被人从悬崖上扔下去过，被人用锤砸过脸，也被自己的锤砸过脸，还从雷霆崖的升降台上摔下去过不止一次。$B$B那些疼加在一起，都不到蕾扎现在受的一半。希望这茶能帮上忙……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30132, 'zhCN', '战争。说到底总是战争。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30137, 'zhCN', '蜥蜴人把偷走的蛇蛋藏在他们营地中。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30139, 'zhCN', '野生云端翔龙与自然保持着微妙的平衡。它们稀有的蛇蛋极易被敌人夺走。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30140, 'zhCN', '野生云端翔龙与自然保持着微妙的平衡。它们稀有的蛇蛋极易被敌人夺走。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30141, 'zhCN', '野生云端翔龙与自然保持着微妙的平衡。它们稀有的蛇蛋极易被敌人夺走。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30146, 'zhCN', '找到好钓点了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30147, 'zhCN', '挖掘进行得如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30149, 'zhCN', '必需的食材找齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30150, 'zhCN', '<你回来时，小翔龙欢快地转着圈。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30154, 'zhCN', '看来任务已经完成了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30158, 'zhCN', '办妥了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30159, 'zhCN', '那些恶心的滑鳞蜥蜴人难道永远不消停吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30160, 'zhCN', '哎呀，$n，真高兴又见到你。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30168, 'zhCN', '我怀疑他们连我的圣痰盂都偷走了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30179, 'zhCN', '切欣有消息吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30184, 'zhCN', '把“大”字刻进“大猎物猎人”。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30185, 'zhCN', '我一直活在爹的影子里。但从今天起，人们会记住小奈辛瓦里这个名字！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30189, 'zhCN', '$n，今天感觉如何？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30191, 'zhCN', '被偷的那些酒桶找到几个？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30193, 'zhCN', '要喂的嘴可真不少，这是肯定的！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30195, 'zhCN', '采花丰收了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30196, 'zhCN', '我都能听见全村饥肠辘辘的肚子在咕咕叫！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30205, 'zhCN', '我跟你说的那些符文找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30206, 'zhCN', '很久以前，魔古还统治着这片山谷时，这些符石被当作能量之源使用。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30230, 'zhCN', '我们每收缴一件圣物，魔古手里就少一件武器。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30231, 'zhCN', '我总是估不准这些东西能榨出多少汁。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30232, 'zhCN', '让你这样有成就的人反复干这种杂活，我实在开不了口，但眼下确是危难之时。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30256, 'zhCN', '看看那些……呃，这里管它们叫什么来着？哦对，大宝贝！$B$B瞧瞧那些大宝贝！$B$B我觉得我这农夫当得有点门道了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30257, 'zhCN', '嘿，以前没在这儿见过你这张脸！你叫什么名字？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30259, 'zhCN', '我没看见嚼烂的胡萝卜。你没看见嚼烂的胡萝卜。泥爪先生永远不会知道，好吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30265, 'zhCN', '那些神秘的金光到底是什么？我好奇得要命。金币？金杯？还是一打被丢弃的结婚戒指？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30267, 'zhCN', '我不钓鱼就浑身难受。钓鱼就是我的命！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30268, 'zhCN', '<安度因全神贯注地盯着自己的双手，麻利地从蛇身上剔出毒腺。>$B$B在颌骨内侧……第二对毒牙后面两寸的地方……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30275, 'zhCN', '你手里拿着什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30277, 'zhCN', '圣物找回来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30285, 'zhCN', '那些报告找到了吗？要是太多情报落入魔古手里，我可担心我们前线弟兄的安全。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30291, 'zhCN', '额外的好处是，我的办法保证它们出锅时就熟了！要这都不算现代效率的奇迹，那什么才算？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30300, 'zhCN', '我宁死也不做魔古的囚徒。他们可不是什么仁慈的狱卒。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30318, 'zhCN', '我发誓，她以前从来没这样过。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30322, 'zhCN', '你知道吗，身边有个打手……我是说，像你这样的 $c……还真不错。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30323, 'zhCN', '你说说，那些兔妖怎么可以这么不负责任、这么幼稚？它们知不知道那首饰值多少钱？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30326, 'zhCN', '我敢说猢狲人的传说跟我们自己的差不了多少。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30328, 'zhCN', '尽量别开那些坛子。真开了的话，可别凑近了闻。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30329, 'zhCN', '就把辣椒放在这块案板上吧。我自己可不想碰它们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30330, 'zhCN', '松露不需要太多。说到底只是用来提味的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30331, 'zhCN', '我以前每天进山一趟，就为了练这道炖菜。$B$B那时候，我还年轻。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30332, 'zhCN', '<厨师正忙着为马上要煎的牛排备香料和酱汁。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30334, 'zhCN', '都弄齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30338, 'zhCN', '给我找到一两件漂亮的石头了吗？要是你这么好心，等着的可是一个大大的拥抱！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30339, 'zhCN', '这么多鱼等着钓！我都等不及开始等了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30340, 'zhCN', '这么多鱼等着钓！我都等不及开始等了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30344, 'zhCN', '研究失落的王朝是一回事，亲临他们的古老废墟又是另一回事。$B$B我几个世纪以来头一次这么兴奋！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30346, 'zhCN', '<你感受到守望者维尔德里恩的存在，然后听见他在你脑海中说话。>$B$B嗯。关于“青春之泉”的那些“折磨”说法，我还是不太确定。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30347, 'zhCN', '没有什么比终有一死更能给人紧迫感了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30350, 'zhCN', '荆棘杖妈妈总说，“扭扭乐”能治一切饥饿，反正总有一头管用。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30351, 'zhCN', '我从没见过魔古数量这么多。他们向来讨厌，但从未坏到这个地步。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30353, 'zhCN', '和奈辛瓦里一起打猎我是喜欢的，可他图的是打猎。我图的是钱，而他一分也不给我们。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30355, 'zhCN', '我们每收缴一件圣物，魔古手里就少一件武器。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30363, 'zhCN', '斥候找到了吗？', 0);
