REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30828, 'zhCN', '湖净化了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30891, 'zhCN', '调配得当的话，这些花粉的花精能化解毒素，而不会对身体造成其他持久的伤害。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30894, 'zhCN', '我想找出一种对付螳螂毒的永久办法，让弟兄们一开始就不会中招。拼凑出来可能要花些时间。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30895, 'zhCN', '回来得比预想的还快。种子带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30897, 'zhCN', '我妈就警告过我会出这种事……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30899, 'zhCN', '又一批飞贼来了。做好准备。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30922, 'zhCN', '这活儿确实脏。$B$B可比挖坟强多了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30931, 'zhCN', '你……你找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30942, 'zhCN', '我要让我爹知道，他看错我了！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30943, 'zhCN', '挥发花找到合适的量了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30945, 'zhCN', '要渡过这一关，光靠运气可不够。希望你找到了我能用上的东西。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30954, 'zhCN', '我们的士兵习惯了用钉锤和木棒作战。可惜，我们没时间讲究传统了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30963, 'zhCN', '我不能让我们的同胞只因一副破了的盔甲就倒下。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30964, 'zhCN', '$n，外面有收获吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30969, 'zhCN', '徽记收集齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30971, 'zhCN', '桥头那边的熊猫人可都指望着我们呢……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30972, 'zhCN', '欢迎来到食堂。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (30998, 'zhCN', '徽记收集齐了吗？', 0);
