REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31008, 'zhCN', '誓剑客们都为自己的佩剑而骄傲。我要把它们摆上我的武器架！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31023, 'zhCN', '你手里拿着什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31024, 'zhCN', '给阔洛克带了什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31041, 'zhCN', '找到蛋了吗？翔龙把蛋产在海滩的巢里，可那些木精灵一有机会就会来偷。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31042, 'zhCN', '黑玉之爪绝不会违抗它们的主人。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31043, 'zhCN', '知识就是力量。这正是魔古如此危险的原因。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31044, 'zhCN', '奇林凶猛，但我在你眼里也看到了同样的凶猛。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31068, 'zhCN', '那是什么卷轴吗？$B$B介意我看看吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31070, 'zhCN', '我在想，该怎么把这些东西加进酒里？磨成粉是不行的——会太糙。$B$B也许直接泡一段时间吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31071, 'zhCN', '找到了吗？真的吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31072, 'zhCN', '我想我开始读懂这预言的后几句了，$n。$B$B匕首弄到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31073, 'zhCN', '我们这儿酿酒不用木头。那会给酒带来一股冲鼻的、寡淡的味道，跟酒似的。$B$B<武啐了一口。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31077, 'zhCN', '<老陈沉浸在悲痛中。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31078, 'zhCN', '我好像看见那边有人，可我过不去这些琥珀光梁。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31080, 'zhCN', '那些东西我一只都没抓着！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31086, 'zhCN', '有收获吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31090, 'zhCN', '我本想跟你一起去采琥珀，但我的才能在这儿更派得上用场。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31107, 'zhCN', '克帕莉·沃尔曾经美轮美奂。琥珀丰饶，四面都是绝佳的猎场。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31108, 'zhCN', '水晶带了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31110, 'zhCN', '粉末找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31112, 'zhCN', '补给弄到手了吗，伙计？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31118, 'zhCN', '找到什么了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31141, 'zhCN', '啊，你收到我的信了，$n……很好。$B我从远方而来，就是要教你的人民 $c 之道。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31146, 'zhCN', '哦，对，那封信是我寄给你的。我希望证明被遗忘者也能学会 $c 的技艺——或许你能帮忙？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31150, 'zhCN', '0', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31156, 'zhCN', '啊，你来了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31160, 'zhCN', '我看它们没什么挑战性，老兄，可你要是腿脚不利索，它们照样会抓破你的脚踝。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31165, 'zhCN', '啊，很高兴认识你。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31168, 'zhCN', '啊，你来了。很好。$B$B我学到了太多东西——你的人民拥有我从未见过的浩瀚知识。尽管事实让我自愧不如，我也希望能把我族的道统传授给你。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31176, 'zhCN', '海星的汁液能让我神智清明。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31177, 'zhCN', '我还有许多事要做。我越早能战斗，就能越早回到议会。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31178, 'zhCN', '饮下仇敌之血，便得仇敌之力。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31184, 'zhCN', '说实话，我倒希望石斑鱼把那份旧宪章给吃了。$B$B等等，那它最后还是会漂到这儿来。该死！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31186, 'zhCN', '<这一定是你见过的最可怜的狮头海豹。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31188, 'zhCN', '亲眼见过有人被裂牙兽吞掉之后，我真不明白你为什么甘愿把它们的牙挂在脖子上，不过随你便。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31208, 'zhCN', '你感受过毒尾蝎的螫刺吗？多么美妙的疼痛。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31209, 'zhCN', '圣甲虫的翅膀碾碎后，能制成极细的白色致命粉末。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31210, 'zhCN', '有时候，最美的东西也最危险。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31232, 'zhCN', '你带来了什么学识？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31233, 'zhCN', '这些树还年轻。它们还不是克帕莉。$B$B它们的树汁如同清水，而真正的克帕莉树之汁宛如美酒。$B$B必须让它们继续生长。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31234, 'zhCN', '哦哦，你给我带来了什么美味的好东西？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31238, 'zhCN', '给阔洛克找到合适的口粮了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31241, 'zhCN', '小笨猴，搞到啥了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31251, 'zhCN', '$n，带肉的那部分呢？我们需要它们！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31254, 'zhCN', '又是陌生人？这一天真是考验我的极限。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31255, 'zhCN', '又是陌生人？这一天真是考验我的极限。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31260, 'zhCN', '我本想亲自去会会那只虎，可说实话，我还想活着……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31262, 'zhCN', '我亲眼看见那只鸟一喙刺穿了老虎的脸。这是什么鬼地方，鸟居然是老虎的天敌？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31268, 'zhCN', '它们仍在抵抗我的声波操纵。我必须弄明白原因。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31279, 'zhCN', '有我的信吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31281, 'zhCN', '让我看看你能不能服从指令。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31286, 'zhCN', '蜥蜴人很少这么大胆。', 0);
