REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31332, 'zhCN', '我真的很想当厨师，可别的孩子几个月前就开工了。没有你的帮忙，我怎么也追不上。', 0);
