REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31357, 'zhCN', '我们必须赶在欣和他的部族找到之前，把灯笼、天平、卷轴和弓夺回来。', 0);
