REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31458, 'zhCN', '情报就是力量，复苏者。掌握情报最多的人，永远握有最大的权力。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31465, 'zhCN', '蜂巢之毒不仅会是我们的新武器，还能帮我们判断虫群现在处于哪个阶段。', 0);
