REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31473, 'zhCN', '智慧印记常见于研习奥术的人身上，而力量印记通常出现在崇尚蛮力的人身上。$B$B这不绝对，但或许能帮你找到需要的东西。', 0);
