REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31513, 'zhCN', '<你手中已握有一把剑，准备去取另一把。>$B$B<剑后雕像上的铭文写着：“天佑之手”。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31514, 'zhCN', '<事情尚未完结。只要怀特迈恩还能死而复生，血色十字军就不会有穷尽。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31515, 'zhCN', '<你手中已握有一把剑，准备去取另一把。>$B$B<剑后雕像上的铭文写着：“天佑之手”。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31516, 'zhCN', '<事情尚未完结。只要怀特迈恩还能死而复生，血色十字军就不会有穷尽。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31534, 'zhCN', '我也说不清。也许是天天盯着那座酿酒厂看出来的毛病，但我就是觉得……我想酿出整个山谷最好的酒……不……全潘达利亚最好的酒！$B$B哦，这梦想挺傻的，对吧？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31535, 'zhCN', '手上没有食材，可学不会做饭。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31536, 'zhCN', '食材存放不当会变质的。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31539, 'zhCN', '这是个宏大的工程。即使是你这样的巧匠，也要花上大量的时间和心血。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31603, 'zhCN', '虫群可怕的进军中，一些被腐化的克帕莉被打得粉碎，被煞感染的琥珀碎片散落各地。$B$B把你旅途中找到的都带给我，好让它们得到妥善处置。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31681, 'zhCN', '我本想跟你一起去采琥珀，但我的才能在这儿更派得上用场。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31690, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31691, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31692, 'zhCN', '什么事？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31700, 'zhCN', '你看见他们脸上的表情了吗？他们疯了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31704, 'zhCN', '<小翔龙天真无邪地看着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31708, 'zhCN', '<你的翔龙欢快地跟你打招呼。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31710, 'zhCN', '你一回来，你的翔龙就来了精神。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31713, 'zhCN', '酒找回来了吗？我……我快撑不住了……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31714, 'zhCN', '几个世纪以来，云端翔龙骑士团一直努力让云端翔龙成为忠实的伙伴。我们的善意能唤出这些生灵最好的一面。$B$B可惜，暴力和愤怒会很快把它们变成毁灭性的怪物。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31716, 'zhCN', '<小翔龙兴致勃勃地看着你。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31784, 'zhCN', '你手里拿着什么，$n？', 0);
