REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31809, 'zhCN', '<班眯起眼睛打量你。>$B$B你身上有股……说不出的不同。变了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31945, 'zhCN', '可别小瞧了大葱。它看着小而不起眼，却能调出绝妙的滋味。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31946, 'zhCN', '兔妖爱胡萝卜，恨芜菁。我也恨芜菁。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31947, 'zhCN', '我的每头牦牛都有小名。有毛毛，有蓬蓬，有绒绒，有绵绵，还有……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31948, 'zhCN', '山谷里的水，是从北边的永恒之泉流下来的。据说这些水有着奇妙的魔法特性。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (31949, 'zhCN', '麻利点行吗？老婆子我不比从前了，时日无多。嗝儿屁之前，我还想再尝一口那酱汁呢！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32016, 'zhCN', '愿这些幸运符为你带来大好运，$n。', 0);
