REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32120, 'zhCN', '你得把那些灵魂打碎，才能收集它们的精华。动手吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32130, 'zhCN', '耳朵，$n，我要看耳朵！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32131, 'zhCN', '石头搞到了吗？俺要炸东西！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32137, 'zhCN', '这么说这条海湾到底还是派上用场了？勤俭节约，缺啥不缺，我看是这个理！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32141, 'zhCN', '你在下面有没有碰巧捡到什么亮闪闪的东西？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32149, 'zhCN', '木材砍齐了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32151, 'zhCN', '石头给我们带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32152, 'zhCN', '士兵，得把那些攻城破坏者收拾掉！', 0);
