REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32197, 'zhCN', '这回又给我带了啥？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32199, 'zhCN', '老板娘想要蒸锅，是吧？那她怎么不自己下来蒸啊！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32233, 'zhCN', '那么？找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32234, 'zhCN', '圣物找到了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32243, 'zhCN', '上头找到什么了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32244, 'zhCN', '你查明什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32257, 'zhCN', '我们完全有能力处理这次挖掘。我知道是大酋长派你来的，可要是他让我们安心干活，成果会来得更快。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32264, 'zhCN', '东西带了吗？书带了吗？！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32292, 'zhCN', '怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32318, 'zhCN', '我的草药是沃金活下去的唯一指望。我不敢离开他半步。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32319, 'zhCN', '$R，你千里迢迢来见我。说吧。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32332, 'zhCN', '啊，聪明的小家伙回来了。我的琥珀带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32333, 'zhCN', '金属酿液在你手上吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32336, 'zhCN', '印古是个了不起的猢狲。好头领，爱办派对，还有好酒。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32337, 'zhCN', '脑袋搞到了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32338, 'zhCN', '魔古当年是怎么找到那药膏的，堪称奇迹。$B$B不过自从世界崩碎之后，世事早已大不同了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32342, 'zhCN', '陷阱带来了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32343, 'zhCN', '$R，精华可不会自己长出来。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32377, 'zhCN', '你端详着这身组装好的库卡隆伪装，耳机里的对讲机噼啪作响。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32379, 'zhCN', '魔古那边查到什么了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32397, 'zhCN', '找到什么了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32446, 'zhCN', '那遥控器到底管什么用？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32448, 'zhCN', '书里的东西，你永远猜不到。尤其是古老的熊猫人典籍。$B$B我等不及想看看这忆酒的效果了。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32494, 'zhCN', '面具都在吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32505, 'zhCN', '我的每一块碎片都必须带回。哪怕少一颗小石子，我就当我们的协议作废。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32506, 'zhCN', '一股浓重的阴霾笼罩着这座岛……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32556, 'zhCN', '$c，给我带了什么？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32557, 'zhCN', '在那边找到什么了吗？有什么能用的东西吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32558, 'zhCN', '面具在哪儿？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32571, 'zhCN', '一股浓重的阴霾笼罩着这座岛……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32587, 'zhCN', '怎么样？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32589, 'zhCN', '我们的计划得手了吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32591, 'zhCN', '你从雷电王座带回什么了？雷电之王的凶名名副其实吗？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32594, 'zhCN', '风暴领主纳拉克呢？长枪呢？快说细节！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32596, 'zhCN', '到目前为止你查明什么了？$B$B我们要把情报一网打尽！', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32597, 'zhCN', '雷电之王！他怎么样了？', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32599, 'zhCN', '等雷神之力与我的法杖融为一体，我们将势不可挡。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32607, 'zhCN', '时间每过一小时，我们就离降服雷电之王更近一步。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32608, 'zhCN', '雷电之王的强大举世闻名。想打败他，我们就得抓住一切优势。', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32613, 'zhCN', '库玛要的东西带来了吗？', 0);
