REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32615, 'zhCN', '你是谁？为什么又回来了？嘿嘿嘿……', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32616, 'zhCN', '<库玛狂笑着朝你比划。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32617, 'zhCN', '<库玛开始绕着他的小屋手舞足蹈。>', 0);
REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (32633, 'zhCN', '那部典籍找到了吗？', 0);
